 private class Keys:SecretStore {
  var reads=0;var writes=0
  override fun load(scope:String):String {require(scope=="zotero.primary"){"Borrowed migration must never read another secret scope"};reads++;return "synthetic-api"}
  override fun save(scope:String,secret:String){writes++;error("No secret copy")};override fun remove(scope:String){writes++;error("No secret removal")}
 }
 private class Grant(private val target:ZoteroDavTarget):ZoteroDavAuthorization {
  var active=true;var published=false;var authorizations=0;var onPublished:()->Unit={}
  override fun requireCurrent(target:ZoteroDavTarget){check(active&&canonical(this.target.binding())==canonical(target.binding()))}
  override fun requirePublished(target:ZoteroDavTarget){requireCurrent(target);onPublished();check(published)}
  override fun authorization(target:ZoteroDavTarget,check:()->Unit):String{check();requirePublished(target);authorizations++;return "Basic c3ludGhldGljOnN5bnRoZXRpYw=="}
 }
 private class Remote:ZoteroTransport,DavWireTransport {
  val items=linkedMapOf<String,JSONObject>();val storage=mutableMapOf<String,ByteArray>();val dav=mutableMapOf<String,ByteArray>();val requests=mutableListOf<Request>();var apiWrites=0;var patches=0;var davPuts=0;var storageUploads=0;var corruptStorage=false;var quota=true;var cancelAfterZip=false;var losePatch=false
  var downloadGate:CompletableDeferred<Unit>?=null;var downloadStarted=CompletableDeferred<Unit>();var afterDownload:(String)->Unit={};var downloadedTarget:File?=null;var afterZip:(String)->Unit={}
  fun md5(b:ByteArray)=java.security.MessageDigest.getInstance("MD5").digest(b).joinToString(""){"%02x".format(it.toInt()and 255)}
  private fun envelope(key:String)=JSONObject().put("key",key).put("version",items[key]!!.getLong("version")).put("library",JSONObject().put("type","user").put("id",123)).put("data",items[key])
  override suspend fun request(request:Request,limit:Int):HttpBytes {
   requests+=request;val p=request.url.encodedPath;fun reply(code:Int,s:String="")=HttpBytes(code,emptyMap(),s.toByteArray())
   if(request.url.host=="files.example.org") {assertNull(request.header("Zotero-API-Key"));val b=Buffer();request.body!!.writeTo(b);val bytes=b.readByteArray();storage[p.removePrefix("/")]=bytes.copyOfRange(3,bytes.size-3);storageUploads++;return reply(201)}
   assertEquals("synthetic-api",request.header("Zotero-API-Key"));assertNull(request.header("Authorization"))
   if(p=="/keys/current")return reply(200,JSONObject().put("userID",123).put("access",JSONObject().put("user",JSONObject().put("library",true).put("write",true).put("files",true).put("notes",true))).toString())
   if(request.method=="POST"&&p.endsWith("/items")){apiWrites++;val b=Buffer();request.body!!.writeTo(b);val a=JSONArray(b.readUtf8());for(i in 0 until a.length()){val item=a.getJSONObject(i);val key=item.getString("key");require(!items.containsKey(key));items[key]=item.copy().put("version",1).also{if(it.optString("itemType")=="attachment")it.put("md5",JSONObject.NULL).put("mtime",JSONObject.NULL)}};return reply(200,"{\"failed\":{}}")}
   val key=request.url.pathSegments[3]
   if(request.method=="GET")return if(items.containsKey(key))reply(200,envelope(key).toString())else reply(404)
   if(request.method=="PATCH"){patches++;val actual=items[key]!!;if(request.header("If-Unmodified-Since-Version")!=actual.getLong("version").toString())return reply(412);val b=Buffer();request.body!!.writeTo(b);val body=JSONObject(b.readUtf8());actual.put("md5",body.getString("md5")).put("mtime",body.getLong("mtime")).put("version",actual.getLong("version")+1);if(losePatch){losePatch=false;throw IOException("synthetic lost PATCH reply")};return reply(204)}
   if(request.method=="POST"&&p.endsWith("/file")){val b=Buffer();request.body!!.writeTo(b);val form=b.readUtf8();if(form.startsWith("upload=")){items[key]!!.put("md5",md5(storage[key]!!)).put("mtime",1000).put("version",items[key]!!.getLong("version")+1);return reply(204)};if(quota&&items[key]!!.getString("filename")=="analysis.json")return reply(413);return reply(200,JSONObject().put("url","https://files.example.org/$key").put("prefix","PRE").put("suffix","END").put("contentType","application/octet-stream").put("uploadKey","synthetic-upload").toString())}
   error("Unhandled test boundary")
  }
  override suspend fun download(request:Request,target:File,limit:Long):HttpFile=downloadFile(request,target,limit,null)
  override suspend fun downloadOwned(request:Request,target:File,limit:Long,owned:(ZoteroOwnedFileReceipt)->Unit):HttpFile=downloadFile(request,target,limit,owned)
  private suspend fun downloadFile(request:Request,target:File,limit:Long,owned:((ZoteroOwnedFileReceipt)->Unit)?):HttpFile {
   requests+=request;downloadedTarget=target
   if(request.url.host=="api.zotero.org")return HttpFile(302,mapOf("Location" to "https://files.example.org/${request.url.pathSegments[3]}"),0,null)
   assertNull(request.header("Zotero-API-Key"));val key=request.url.pathSegments.single();downloadStarted.complete(Unit);downloadGate?.await();val bytes=storage[key]!!.copyOf();if(corruptStorage)bytes[0]=(bytes[0].toInt()xor 1).toByte();require(bytes.size<=limit);Files.newByteChannel(target.toPath(),java.nio.file.StandardOpenOption.CREATE_NEW,java.nio.file.StandardOpenOption.WRITE,java.nio.file.LinkOption.NOFOLLOW_LINKS).use{out->owned?.invoke(ZoteroOwnedDownloadTestFiles.receipt(target));out.write(ByteBuffer.wrap(bytes))};afterDownload(key);return HttpFile(200,emptyMap(),bytes.size.toLong(),sha256(bytes))
  }
  override suspend fun exchange(request:Request,limit:Long,reply:DavReplyFile?,check:()->Unit):DavWireReply {
   check()
   if(request.url.host=="api.zotero.org"){val r=this.request(request,limit.toInt());return DavWireReply(r.code,r.headers,r.bytes,r.bytes.size.toLong(),sha256(r.bytes))}
   requests+=request;assertEquals("dav.example.org",request.url.host);assertNull(request.header("Zotero-API-Key"));assertTrue(request.header("Authorization").orEmpty().startsWith("Basic "));val path=request.url.encodedPath
   if(request.method=="PUT"){assertEquals("*",request.header("If-None-Match"));if(dav.containsKey(path))return DavWireReply(412,emptyMap());val b=Buffer();request.body!!.writeTo(b);dav[path]=b.readByteArray();davPuts++;if(path.endsWith(".zip")){afterZip(path.substringAfterLast('/').substringBefore('.'));if(cancelAfterZip){cancelAfterZip=false;throw CancellationException("synthetic cancel")}};return DavWireReply(201,emptyMap())}
   val bytes=dav[path]?:return DavWireReply(404,emptyMap());check();if(reply!=null){reply.open().use{val b=ByteBuffer.wrap(bytes);while(b.hasRemaining())it.write(b)};return DavWireReply(200,emptyMap(),bytes=bytes.size.toLong(),sha256=sha256(bytes))};return DavWireReply(200,emptyMap(),bytes,bytes.size.toLong(),sha256(bytes))
  }
 }
 private class Fixture {
  val root=Files.createTempDirectory("storage-migration-service-").toFile().canonicalFile
  val research=File(root,"Research").also{it.mkdir()};val keys=Keys();val remote=Remote();var preparations=0
  val provider=ZoteroMaterialProvider { preparations++;val roles=listOf("source-metadata" to "application/json","pdf" to "application/pdf","guide" to "text/html","analysis" to "application/json");val materials=roles.map{(role,type)->val f=File(root,"$role-original").apply{writeText("controlled-original-$role")};ZoteroMaterial(role,role,type,f,sha256=sha256(f.readBytes()))}+ZoteroMaterial("note","note","text/html",noteHTML="<div>controlled note</div>",sha256=sha256("<div>controlled note</div>".toByteArray()));ZoteroMaterials("arxiv:2501.00001","a".repeat(64),JSONObject().put("itemType","preprint").put("title","Source-bound controlled paper"),materials) }
  fun service()=ZoteroService(research,keys,provider,remote,davFactory={dir,k->ZoteroDavBackend(dir,k,remote)},migrationFiles=ZoteroOwnedDownloadTestFiles)
  var service=service();lateinit var parentID:String;lateinit var original:Map<String,Pair<String,Long>>
  suspend fun start(){service.execute("save",JSONObject().put("libraryType","users").put("libraryID","123"));parentID=service.execute("prepare").getString("preparedID");fails{service.execute("archive",JSONObject().put("preparedID",parentID))};assertEquals(3,remote.storageUploads);original=parentDir().listFiles()!!.associate{it.name to(sha256(it.readBytes())to it.lastModified())};assertEquals("failed",journal(parentID).getString("status"))}
  fun parentDir()=File(research,"ZoteroArchives/$parentID")
  fun journal(id:String)=JSONObject(File(research,"ZoteroArchives/$id/journal.json").readText())
  fun protected(){assertEquals(original,parentDir().listFiles()!!.associate{it.name to(sha256(it.readBytes())to it.lastModified())});assertEquals(1,preparations);assertEquals(0,keys.writes)}
  suspend fun preview():Pair<String,Grant>{val id=service.beginStorageMigrationPreview(parentID,"https://dav.example.org/dav/","synthetic-account");val grant=Grant(service.migrationTarget(id));val p=service.previewStorageMigration(id,grant);assertEquals(3,p.getInt("storageFilesVerified"));return id to grant}
  suspend fun confirm(id:String,g:Grant)=service.confirmStorageMigration(id,g){body->val prepared=body();g.published=true;prepared}.getString("journalID")
  fun close(){root.deleteRecursively()}
 }
