 @Test fun failedDownloadCleansOnlyItsOwnedTemporary()=runBlocking{val f=Fixture();try{f.start();f.remote.afterDownload={throw IOException("controlled readback failure")};fails{f.preview()};assertTrue(File(f.root,"ZoteroMigrationWork").listFiles()!!.isEmpty());f.protected()}finally{f.close()}}
 @Test fun cancelledDownloadAfterFilePublicationCleansItsTemporary()=runBlocking{val f=Fixture();try{f.start();f.remote.afterDownload={throw CancellationException("controlled publication cancellation")};fails{f.preview()};assertTrue(File(f.root,"ZoteroMigrationWork").listFiles()!!.isEmpty());f.protected()}finally{f.close()}}
 @Test fun replacementTemporaryInodeIsNeverDeleted()=runBlocking{val f=Fixture();try{f.start();f.remote.afterDownload={val file=f.remote.downloadedTarget!!;Files.move(file.toPath(),file.toPath().resolveSibling("owned-renamed"));file.writeText("foreign inode");throw IOException("controlled replacement")};fails{f.preview()};val work=File(f.root,"ZoteroMigrationWork").listFiles()!!.single();assertEquals("foreign inode",File(work,"storage-0.bin").readText());assertTrue(File(work,"owned-renamed").exists());f.protected()}finally{f.close()}}
 @Test fun replacementWorkDirectoryIsNeverWalkedOrDeleted()=runBlocking{val f=Fixture();try{f.start();f.remote.afterDownload={val dir=f.remote.downloadedTarget!!.parentFile;Files.move(dir.toPath(),dir.toPath().resolveSibling("owner-renamed"));assertTrue(dir.mkdir());File(dir,"foreign-marker").writeText("foreign directory");throw IOException("controlled replacement")};fails{f.preview()};val work=File(f.root,"ZoteroMigrationWork").listFiles()!!.single{it.name.startsWith("verify-")};assertEquals("foreign directory",File(work,"foreign-marker").readText());assertTrue(File(f.root,"ZoteroMigrationWork/owner-renamed").exists());f.protected()}finally{f.close()}}


 @Test fun failedCleanupPreservesOriginalCancellationAndForeignDirectory()=runBlocking{
  val f=Fixture();val originalCancellation=CancellationException("controlled original cancellation")
  try{
   f.start();f.remote.afterDownload={val dir=f.remote.downloadedTarget!!.parentFile;Files.move(dir.toPath(),dir.toPath().resolveSibling("owner-renamed"));assertTrue(dir.mkdir());File(dir,"foreign-marker").writeText("preserve");throw originalCancellation}
   val failure=fails{f.preview()};assertTrue(failure is CancellationException);assertEquals("controlled original cancellation",failure.message)
   // Coroutine debug stacktrace recovery may copy the outer cancellation. The actual
   // originally thrown instance, including its cleanup failure, must remain intact.
   val chain=generateSequence(failure as Throwable?){it.cause}.take(8).toList()
   assertEquals(1,chain.count{it===originalCancellation});assertEquals(1,originalCancellation.suppressed.size)
   val cleanup=originalCancellation.suppressed.single();assertTrue(cleanup is IllegalArgumentException)
   assertTrue(cleanup.stackTrace.any{it.className.startsWith(ZoteroStorageReadOnlyVerifier::class.java.name)})
   assertEquals("preserve",File(File(f.root,"ZoteroMigrationWork").listFiles()!!.single{it.name.startsWith("verify-")},"foreign-marker").readText());f.protected()
  }finally{f.close()}
 }

}
